const k = $input.first().json;
const fmt = n => Number(n).toLocaleString('en-US');
const text = [
  `Customer 360 daily summary for ${k.kpi_date}`,
  ``,
  `Transactions: ${fmt(k.transactions)} (value BDT ${fmt(k.transaction_value)})`,
  `App daily active users: ${fmt(k.app_daily_active_users)}`,
  `Complaints opened: ${k.complaints_opened} | Accounts closed: ${k.accounts_closed}`,
  `Customers at high churn risk: ${k.high_churn_risk}`,
  `Stage 3 share of loan book: ${k.stage3_pct}%`,
  `Data quality issues: ${k.dq_issues}`
].join('\n');
return [{ json: { subject: `Customer 360 | ${k.kpi_date}`, text, dq_issues: Number(k.dq_issues) } }];
